import{_ as i,o as a,c as t,a5 as r}from"./chunks/framework.UjrY2eRK.js";const m=JSON.parse('{"title":"Use Drizzle within runtime-specific storage adapters","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr/0023-use-drizzle-within-runtime-specific-storage-adapters.md","filePath":"architecture/adr/0023-use-drizzle-within-runtime-specific-storage-adapters.md","lastUpdated":1788169631000}'),n={name:"architecture/adr/0023-use-drizzle-within-runtime-specific-storage-adapters.md"};function s(o,e,c,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="use-drizzle-within-runtime-specific-storage-adapters" tabindex="-1">Use Drizzle within runtime-specific storage adapters <a class="header-anchor" href="#use-drizzle-within-runtime-specific-storage-adapters" aria-label="Permalink to &quot;Use Drizzle within runtime-specific storage adapters&quot;">​</a></h1><p>The D1 and Bun SQLite adapters will use Drizzle for typed schema and query construction while retaining reviewed SQL wherever exact transaction, migration, atomic-claim, PRAGMA, or runtime API behavior is clearer and safer at the lower level. One canonical set of reviewed SQL migrations continues to feed both runtimes, and the adapters remain separate implementations of the same behavioral ports and contract suite rather than one emulated database layer.</p><p>This decision supersedes ADR 0017&#39;s blanket ORM exclusion. Its behavioral-port boundary, runtime-specific adapters, shared concurrency and failure semantics, canonical migration lineage, explicit transaction and migration behavior, and justified raw SQL exceptions remain in force.</p><p>This decision also supersedes only ADR 0013&#39;s two-package runtime ceiling. The focused allowlist becomes exactly pinned <code>drizzle-orm</code>, <code>jose</code>, and Zod; <code>drizzle-kit</code> remains development-only. The initial adoption pins <code>drizzle-orm</code> 0.45.2 and <code>drizzle-kit</code> 0.31.10, keeps both offline generation profiles on one reviewed migration and snapshot lineage, and leaves Wrangler and the Bun startup runner responsible for applying SQL.</p>',4)])])}const h=i(n,[["render",s]]);export{m as __pageData,h as default};
